{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "`judge-jev validate` MUST take one input file."
  },
  "record": {
    "id": "REQ-JEV-0210",
    "title": "Validate command",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "",
      "statements": [
        {
          "modal": "Must",
          "text": "`judge-jev validate` MUST take one input file."
        },
        {
          "modal": "Must",
          "text": "`judge-jev validate` MUST take one input-kind flag with that file:\n`--tree` (quality tree), `--questions` (question set), `--answers`\n(answers file), `--index` (Raptor import index) or `--requests` (batch\nrequest stream)."
        },
        {
          "modal": "Must",
          "text": "`judge-jev validate` MUST check the file with the model `judge-jev`\napplies to that input kind before its first Jev request (ADR-JEV-0005)."
        },
        {
          "modal": "Must",
          "text": "Every refusal from `judge-jev validate` MUST name the field path."
        },
        {
          "modal": "Must",
          "text": "Every refusal from `judge-jev validate` MUST name the rule the field\nbreaks."
        },
        {
          "modal": "Must",
          "text": "`judge-jev validate --answers` MUST apply the answers-file envelope that\n`--answers-file` applies before the first request."
        },
        {
          "modal": "Must",
          "text": "The answers-file envelope MUST require an object of string keys."
        },
        {
          "modal": "Must",
          "text": "The answers-file envelope MUST require each key's value to be an object\nor a non-empty list of objects."
        },
        {
          "modal": "Must",
          "text": "The answers-file envelope MUST require an object with `__error__` to hold\nonly a string code of at most 64 characters."
        },
        {
          "modal": "Must",
          "text": "With `--answers-file`, `judge-jev` MUST check what an answer holds (its\nquestions, choices and probabilities) after the send, as\n`JEV.RESPONSE_INVALID`."
        },
        {
          "modal": "MustNot",
          "text": "`judge-jev validate` MUST NOT call Jev."
        },
        {
          "modal": "MustNot",
          "text": "The answers-file envelope MUST NOT cover what an answer holds (its\nquestions, choices and probabilities)."
        }
      ]
    },
    "rationale": "A tree variation checked before a run costs nothing; one refused after a\npaid call wastes it.\n\nThe answers file stands in for Jev's response, so what an answer holds is\nchecked after the send, not in the envelope.",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "Every input the sweep tests refuse in `quality` is refused by\n`judge-jev validate` with the same field path.",
          "checked": false
        },
        {
          "text": "The shipped trees and question sets pass `judge-jev validate`.",
          "checked": false
        }
      ],
      "test_evidence": []
    },
    "dependencies": {
      "text": "",
      "requires": [],
      "related": []
    },
    "product_applicability": {
