    "requirement_statement": {
      "text": "",
      "statements": [
        {
          "modal": "Must",
          "text": "For every input, every `judge-jev` command MUST print exactly one JSON\nobject."
        },
        {
          "modal": "Must",
          "text": "When a `judge-jev` command completes, the JSON object it prints MUST be\nits result."
        },
        {
          "modal": "Must",
          "text": "When a `judge-jev` command does not complete, the JSON object it prints\nMUST be a typed error."
        },
        {
          "modal": "Must",
          "text": "`judge-jev` MUST refuse an invalid tree, question set, index, request\nstream or run directory before its first Jev request."
        },
        {
          "modal": "Must",
          "text": "`judge-jev` MUST check that every log event of a request (the request,\nJev's largest possible answer and the result) fits the logger's event\nsize limit before sending the request."
        }
      ]
    },
    "rationale": "Rand Lee, 2026-11-08: \"Crash is not acceptable for any input.\" A refusal\nafter a paid call wastes the call; a crash loses its answer.",
