{
  "statement": {
    "index": 6,
    "modal": "MustNot",
    "text": "`judge-jev` MUST NOT truncate a definition."
  },
  "record": {
    "id": "REQ-JEV-0212",
    "title": "Targeted definitions",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "",
      "statements": [
        {
          "modal": "Must",
          "text": "A definition MUST be attachable to a record alone, or to a record and\none location under evaluation."
        },
        {
          "modal": "Must",
          "text": "A request about a record MUST carry, in its state next to the record, only\nthe definitions attached to that record alone, plus those attached to\nthat record and the request's location."
        },
        {
          "modal": "Must",
          "text": "A request with no matching definition MUST be identical to the request\nsent without definitions."
        },
        {
          "modal": "Must",
          "text": "`judge-jev` MUST refuse, before sending, a request whose definitions take\nit over the size limit."
        },
        {
          "modal": "Must",
          "text": "Every request's log event MUST record the digest of each definition it\ncarried."
        },
        {
          "modal": "MustNot",
          "text": "`judge-jev` MUST NOT truncate a definition."
        }
      ]
    },
    "rationale": "Rand Lee, 2026-11-08: \"we can NOT write a single definition file and add it\nto every prompt\" when running over 1000 to 2000 records with 1 to 200\nlocations each. A record-only definition \"makes the req/nfr/adr w/ confusing\nterm carry the definition w/ it for all jev calls\"; a record-and-location\ndefinition \"would only be added to specific data (code/prompt/skill) which\nrequires clarification\".",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "With definitions linked to record A only, the requests for record B\nare byte-identical to a run without definitions.",
          "checked": false
        },
        {
          "text": "The requests for record A carry exactly A's definitions, and their log\nevents list those definitions' digests.",
          "checked": false
        },
        {
          "text": "A definition attached to record A and location X is carried by A's\nrequest for X and by no other request about A.",
          "checked": false
        }
      ],
      "test_evidence": []
    },
