{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "`judge-jev` MUST provide a comparison of one or more candidate\ndefinitions."
  },
  "record": {
    "id": "REQ-JEV-0213",
    "title": "A definition is kept only when it changes an answer",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "",
      "statements": [
        {
          "modal": "Must",
          "text": "`judge-jev` MUST provide a comparison of one or more candidate\ndefinitions."
        },
        {
          "modal": "Must",
          "text": "The comparison MUST run the requests the candidate definitions would\nreach with the candidates."
        },
        {
          "modal": "Must",
          "text": "The comparison MUST run the same requests without the candidates."
        },
        {
          "modal": "Must",
          "text": "The comparison MUST report each answer's choice with and without the\ncandidates."
        },
        {
          "modal": "Must",
          "text": "The comparison MUST report each answer's confidence with and without the\ncandidates."
        },
        {
          "modal": "Must",
          "text": "The comparison MUST report the candidates as material when an answer's\nchoice flips or its confidence crosses the decision threshold, and as not\nmaterial when every change stays on the same side of the threshold."
        },
        {
          "modal": "Must",
          "text": "The comparison MUST record the threshold it applied."
        }
      ]
    },
    "rationale": "Rand Lee, 2026-11-08: \"if adding the definition does not impact the scores\nused in the rubric, they aren't necessary to add\"; \"Moving from 90->95\nconfidence doesn't matter. A change from 20%->50% would be material if\nother changes get it over the threshold.\"",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "With fixture answers where the definition flips one answer, the\ncomparison reports it as material.",
          "checked": false
        },
        {
          "text": "With fixture answers that are the same with and without the\ndefinition, the comparison reports it as not material.",
          "checked": false
        },
        {
          "text": "A confidence move from 0.90 to 0.95 on the same side of the threshold\nis not material. Two candidates that each move an answer part of the way,\nand together across the threshold, are material when compared together.",
          "checked": false
        }
      ],
      "test_evidence": []
    },
