{
  "statement": {
    "index": 1,
    "modal": "Must",
    "text": "`judge-jev doctor` MUST validate every tree, question set and definitions\nfile in the scope against its schema."
  },
  "record": {
    "id": "REQ-JEV-0215",
    "title": "Doctor command",
    "status": "Draft",
    "version": "0.1.0",
    "created": "2026-11-07",
    "last_updated": "2026-11-08",
    "owner": "Rand Lee",
    "supersedes": null,
    "superseded_by": null,
    "requirement_statement": {
      "text": "",
      "statements": [
        {
          "modal": "Must",
          "text": "`judge-jev doctor` MUST validate every tree, question set and definitions\nfile in the scope against its schema."
        },
        {
          "modal": "Must",
          "text": "`judge-jev doctor` MUST validate every tree, question set and definitions\nfile in the scope against the ontology's shapes, including edges and\ncycles."
        },
        {
          "modal": "Must",
          "text": "`judge-jev doctor` MUST report each validation failure as an error."
        },
        {
          "modal": "Must",
          "text": "`judge-jev doctor` MUST report a definition with no attachment as a\nwarning."
        },
        {
          "modal": "Must",
          "text": "`judge-jev doctor` MUST report an attachment to a record the Raptor index\ndoes not hold as a warning."
        },
        {
          "modal": "Must",
          "text": "`judge-jev doctor` MUST report an attachment to a location that does not\nexist as a warning."
        },
        {
          "modal": "Must",
          "text": "`judge-jev doctor` MUST report a definition whose source does not exist\nas a warning."
        },
        {
          "modal": "MustNot",
          "text": "`judge-jev doctor` MUST NOT call Jev."
        },
        {
          "modal": "MustNot",
          "text": "A `judge-jev doctor` warning MUST NOT fail the command."
        }
      ]
    },
    "rationale": "Rand Lee, 2026-11-08: \"I would expect judge-jev doctor to report orphans/dead\nlinks as warnings, it would also run schema validation and verify ontology\nfollowed and no cycles.\"",
    "success_criteria": {
      "text": "",
      "acceptance_criteria": [
        {
          "text": "A scope with one orphan definition exits 0 with one warning naming it.",
          "checked": false
        },
        {
          "text": "A scope with a tree that has a cycle exits non-zero with an error\nnaming the cycle.",
          "checked": false
        }
      ],
      "test_evidence": []
    },
